import{z as l,x as s,o as B,c as d,q as o,j as n,D as e,d as A,s as t,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"药品定价","description":"","frontmatter":{"title":"药品定价","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hi-drug-pricing.md","filePath":"econ/hi-drug-pricing.md","lastUpdated":1791063341000}'),p={name:"econ/hi-drug-pricing.md"};function D(h,E,c,m,u,f){const r=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=o('<h1 id="药品定价" tabindex="-1">药品定价 <a class="header-anchor" href="#药品定价" aria-label="Permalink to &quot;药品定价&quot;">​</a></h1><div class="epigraph"><p>一粒新药的第一版要烧掉十年研发，第二粒的边际成本只有几美分；定价问题就是让这两种成本共存，而不把任何一侧的激励烧穿。</p><footer>—— 据 Arrow, Economic Welfare and the Allocation of Resources for Invention, 1962；Nordhaus, Invention, Growth, and Welfare, 1969 整理</footer></div><p><a href="/econ/hi-health-labor">上一课</a>把健康存量接进劳动供给。缺口转向产业与动态：药几乎是最极端的固定成本商品——分子是烧掉的研发，分母是几美分的边际成本，仿制在专利之外随时可行。<a href="/econ/welfare-theorems">福利两定理</a>的完全市场前提在这里被有意打破：专利就是被制造出来的市场不完全，用来买创新。本课写专利期内的定价怎么定、保险怎么改需求、专利到期后价格怎么落；不写审批监管，也不重写专利竞赛的均衡。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两重扭曲叠加，是本课全部内容的骨架。静态侧：垄断定价把价格抬到边际成本之上，可及性下降，死重损失。动态侧：没有排他就没有占有，模仿者零成本进入，研发投入不足——Arrow 的占有性问题，也是<a href="/econ/public-goods">公共物品</a>课非竞争性的另一面：知识造出来一人用不减另一人可用，收费全靠人为排他。保险把两重扭曲拧在一起：患者只付自付份额，需求弹性被第三方支付压低，定价者面对一条更陡的需求曲线——加价更高，静态损失更大。定价因此不能只看产业，必须连着保单写。</p><p><span class="marginnote">拉姆齐逻辑倒着用：拉姆齐定价让弹性低的市场承担高加价，是被动地按弹性分摊；第三方支付是主动地替定价者把弹性压低。方向相反，效果同形——保单越慷慨，药价越硬。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>专利期内的定价是一个静态问题：需求来自有保险的患者，自付 \\((1-c)p\\)，用量对自付价格敏感、对全价迟钝；垄断者在合成的需求曲线上找边际收益等于边际成本。专利长度是动态一侧的旋钮：Nordhaus 的权衡——专利期加长，创新的边际激励上升，静态损失的年数也上升，最优长度停在两者边际相等处。价值定价是第三条路：不按成本、不按竞争，按增量健康收益定价，偿付方用每 QALY 阈值决定买不买——把「动态换静态」写成行政数字。</p><p><span class="marginnote">数字实例：一粒仿制药的原料与制造成本常只有几美分，专利期内同分子的原研药可卖数元甚至数百元。定价与分母（边际成本）几乎无关——你付的其实是摊到每一粒上的研发固定成本。</span></p>',9)),(B(),n(i,null,{default:e(()=>[t(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E7%A0%94%E5%8F%91%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%E5%B7%A8%E5%A4%A7%22%5D%20--%3E%20PAT%5B%22%E4%B8%93%E5%88%A9%EF%BC%9A%E6%9A%82%E6%97%B6%E6%8E%92%E4%BB%96%22%5D%0A%20%20PAT%20--%3E%20MON%5B%22%E4%B8%93%E5%88%A9%E6%9C%9F%E5%86%85%E5%9E%84%E6%96%AD%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20INS%5B%22%E4%BF%9D%E9%99%A9%EF%BC%9A%E8%87%AA%E4%BB%98%E4%BB%BD%E9%A2%9D%E5%8E%8B%E4%BD%8E%E5%BC%B9%E6%80%A7%22%5D%20--%3E%20MON%0A%20%20MON%20--%3E%20DWL%5B%22%E9%9D%99%E6%80%81%E6%8D%9F%E5%A4%B1%EF%BC%9A%E5%8F%AF%E5%8F%8A%E6%80%A7%E4%B8%8B%E9%99%8D%22%5D%0A%20%20EXP%5B%22%E4%B8%93%E5%88%A9%E5%88%B0%E6%9C%9F%22%5D%20--%3E%20GEN%5B%22%E4%BB%BF%E5%88%B6%E8%8D%AF%E8%BF%9B%E5%85%A5%22%5D%0A%20%20GEN%20--%3E%20FALL%5B%22%E4%BB%B7%E6%A0%BC%E5%A4%A7%E5%B9%85%E5%9B%9E%E8%90%BD%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"专利悬崖是这套逻辑最干净的读数：到期后仿制药进入，价格在几年内跌去大半——说明专利期内的价格由排他权而非成本决定，也说明降价没有摧毁创新，因为创新激励已经付过。悬崖同时是设计参数：延长保护（数据独占、专利丛林）推迟悬崖，是在动态激励上再添一份静态损失。价值定价的机制则反过来：把偿付方的谈判力组织起来，用阈值代替分散的自付；楔子不消失，但从价格搬到了新药不进报销目录。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：QALY（质量调整生命年）把「多活几年」与「活得舒不舒服」折成一个数：健康地多活 1 年记 1，带病多活 1 年按生活质量打折记 0.5。偿付方设阈值（如每 QALY 愿付 5 万美元），超过就不进报销目录。")],-1)),(B(),n(i,null,{default:e(()=>[t(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E4%BF%9D%E9%99%A9%E6%8A%A5%E9%94%80%E6%AF%94%E4%BE%8B%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20SELF%5B%22%E6%82%A3%E8%80%85%E5%8F%AA%E7%9C%8B%E8%87%AA%E4%BB%98%E4%BB%B7%20(1-c)p%22%5D%0A%20%20SELF%20--%3E%20ELA%5B%22%E7%94%A8%E9%87%8F%E5%AF%B9%E5%85%A8%E4%BB%B7%20p%20%E5%8F%98%E8%BF%9F%E9%92%9D%3A%20%E5%BC%B9%E6%80%A7%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20ELA%20--%3E%20CURVE%5B%22%E5%9E%84%E6%96%AD%E8%80%85%E9%9D%A2%E5%AF%B9%E6%9B%B4%E9%99%A1%E7%9A%84%E9%9C%80%E6%B1%82%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20CURVE%20--%3E%20UP%5B%22%E6%9C%80%E4%BC%98%E5%8A%A0%E4%BB%B7%E6%9B%B4%E9%AB%98%2C%20%E5%85%A8%E4%BB%B7%20p%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20UP%20--%3E%20LOOP%5B%22%E6%82%A3%E8%80%85%E8%87%AA%E4%BB%98%20(1-c)p%20%E4%B9%9F%E8%B7%9F%E7%9D%80%E6%B0%B4%E6%B6%A8%E8%88%B9%E9%AB%98%22%5D%0A%20%20LOOP%20--%3E%20DWL%5B%22%E9%9D%99%E6%80%81%E6%AD%BB%E9%87%8D%E6%8D%9F%E5%A4%B1%E8%A2%AB%E4%BF%9D%E9%99%A9%E6%94%BE%E5%A4%A7%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=o('<p>全球市场再加一层：同一分子在不同国家按支付意愿分层定价，参考定价与平行进口把低价国拉向高价国——分层定价与套利的拉锯，是本课楔子在空间上的版本。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写临床试验的监管与审批时滞，不写生物类似药的替代细则，也不写竞赛均衡与奖品设计——那是创新与专利竞赛课的对象。三点易错：把药价贵全归给贪婪，会漏掉第三方支付对弹性的压低；把取消专利当普惠，会漏掉模仿者进入对研发的清零；把 QALY 阈值当纯技术参数，会漏掉它是分配判断，不是测量。</p><p><span class="marginnote">常见误区：把专利悬崖读成「暴利被戳破」。悬崖后价格跌去大半，恰恰说明专利期内的价格里含着创新激励的分期偿还；一刀切取消专利，等于把已经卖出去的激励再赖一次账，下一款药就没人垫钱了。</span></p><p>后课默认：药品定价是「固定成本、第三方支付、临时排他」三件事的交点。下一课收束整门课程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两重扭曲叠加：静态死重损失与动态研发激励，专利是两者的交换装置。</li><li>保险压低需求弹性，使专利期内的加价更高；保单与药价要一起读。</li><li>专利悬崖证明价格由排他决定；价值定价用 QALY 阈值把权衡写成行政数字。</li><li>分层定价与参考定价是同一楔子的空间版本。</li><li>出处：Arrow 1962；Nordhaus, <em>Invention, Growth, and Welfare</em>, 1969；Ramsey 1927 的定价逻辑；据 Cutler–Zeckhauser 2000 的第三方支付框架整理。</li></ul>',7))])}const _=l(p,[["render",D]]);export{C as __pageData,_ as default};
